inputs = ['wfck', 'cckca', 'khycah', 'xhyavc', 'aufiuc']
outputs = ['wfvk', 'vvkvda', 'khyvxdk', 'xhydavv', 'daufiuv']

print("Inputs:", inputs)
print("Outputs:", outputs)

# Let's manually compare to see patterns
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\nExample {i}: '{inp}' -> '{out}'")
    # Find differences
    diff_positions = []
    for j, (a, b) in enumerate(zip(inp, out)):
        if a != b:
            diff_positions.append((j, a, b))
    if len(inp) != len(out):
        # Check for insertions/deletions
        if len(inp) < len(out):
            for j in range(len(inp)):
                if inp[j] != out[j]:
                    diff_positions.append((j, 'deleted', out[j]))
            # Check remaining characters
            for j in range(len(inp), len(out)):
                diff_positions.append((j, 'inserted', out[j]))
        else:
            for j in range(len(out)):
                if inp[j] != out[j]:
                    diff_positions.append((j, inp[j], 'deleted'))
            # Check remaining characters
            for j in range(len(out), len(inp)):
                diff_positions.append((j, inp[j], 'inserted'))

    print(f"  Differences: {diff_positions}")

