inputs = ['wfck', 'cckca', 'khycah', 'xhyavc', 'aufiuc']
outputs = ['wfvk', 'vvkvda', 'khyvxdk', 'xhydavv', 'daufiuv']

# Let's create a helper to find character mappings
def analyze_transformations(inputs, outputs):
    print("Analyzing transformations...")

    # For each position, see what characters map to what
    max_len = max(len(s) for s in inputs + outputs)

    # Create mapping from input characters to output characters
    char_mappings = {}

    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"\nExample {i}: '{inp}' -> '{out}'")

        # Pad shorter string with None for comparison
        padded_inp = inp.ljust(max_len, '\x00')
        padded_out = out.ljust(max_len, '\x00')

        for j, (char_in, char_out) in enumerate(zip(padded_inp, padded_out)):
            if char_in != char_out and char_in != '\x00':
                if char_in not in char_mappings:
                    char_mappings[char_in] = set()
                char_mappings[char_in].add(char_out)

    print("\nCharacter mappings found:")
    for char_in, char_out_set in char_mappings.items():
        print(f"  '{char_in}' -> {list(char_out_set)}")

    return char_mappings

